package com.aistock.gateway;
import com.aistock.common.ApiExceptionHandler;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import org.springframework.http.ResponseEntity;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class AnalysisProxyTest {
 @Test void forwardsOnlyAnalysisQueryAndSessionHeadersAndCapsBody()throws Exception{var client=mock(ForecastPublicClient.class);when(client.get(anyString(),anyMap(),anyMap())).thenReturn(ResponseEntity.ok("{\"code\":\"OK\",\"data\":{}}".getBytes()));var mvc=MockMvcBuilders.standaloneSetup(new AnalysisApiProxyController(client,new ObjectMapper())).setControllerAdvice(new ApiExceptionHandler()).build();mvc.perform(get("/api/v1/stock-analyses").param("instrumentId","SH600030").param("from","2026-07-07").param("to","2026-10-07").param("ownerId","forged").header("Cookie","AISTOCK_SESSION=fixture").header("X-Role","ADMIN").header("X-Service-Token","forged")).andExpect(status().isOk());var headers=ArgumentCaptor.forClass(Map.class);var query=ArgumentCaptor.forClass(Map.class);verify(client).get(eq("stock-analyses"),query.capture(),headers.capture());assertEquals(Map.of("instrumentId","SH600030","from","2026-07-07","to","2026-10-07"),query.getValue());assertFalse(headers.getValue().containsKey("X-Service-Token"));assertFalse(headers.getValue().containsKey("X-Role"));mvc.perform(post("/api/v1/stock-analyses").content("x".repeat(2049))).andExpect(status().isPayloadTooLarge());verifyNoMoreInteractions(client);assertFalse(ProxyHeaderPolicy.allowed("POST","/api/v1/stock-analyses/00000000-0000-0000-0000-000000000001"));mvc.perform(get("/internal/v1/market/analysis-evidence/SH600030")).andExpect(status().isNotFound());}

 @Test void predictionOptionsHasExactGetRouteAndQueryPolicy()throws Exception{var client=mock(ForecastPublicClient.class);when(client.get(anyString(),anyMap(),anyMap())).thenReturn(ResponseEntity.ok("{}".getBytes()));var mvc=MockMvcBuilders.standaloneSetup(new AnalysisApiProxyController(client,new ObjectMapper())).setControllerAdvice(new ApiExceptionHandler()).build();mvc.perform(get("/api/v1/stock-analyses/prediction-options").param("instrumentId","SH600030").param("page","2").param("from","forged").header("X-User-Id","forged")).andExpect(status().isOk());var query=ArgumentCaptor.forClass(Map.class);var headers=ArgumentCaptor.forClass(Map.class);verify(client).get(eq("stock-analyses/prediction-options"),query.capture(),headers.capture());assertEquals(Map.of("instrumentId","SH600030","page","2"),query.getValue());assertFalse(headers.getValue().containsKey("X-User-Id"));mvc.perform(post("/api/v1/stock-analyses/prediction-options").content("{}")).andExpect(status().isNotFound());verifyNoMoreInteractions(client);}
}